import type { GlossaryLane } from './termsStudioGlossary';
import type { TermCategoryId, TermLesson } from './termsStudio';

type Row = readonly [
  slug: string,
  label: string,
  blurb: string,
  keyIdea: string,
  exampleOne: string,
  exampleTwo: string,
  caution: string,
  related?: string,
];

function group(category: TermCategoryId, lane: GlossaryLane, badge: TermLesson['badge'], whenToUse: string, rows: Row[]): TermLesson[] {
  return rows.map(([slug, label, blurb, keyIdea, exampleOne, exampleTwo, caution, related]) => ({
    slug,
    label,
    category,
    glossaryLane: lane,
    badge,
    blurb,
    analogy: exampleOne,
    hook: keyIdea,
    explanation: [keyIdea],
    workedExample: { title: 'Example 1', setup: exampleOne, steps: [], takeaway: keyIdea },
    moreExamples: [exampleTwo],
    tryThis: ['Compare the two examples and explain what the term changes.'],
    whenToUse,
    watchFor: caution,
    related: related?.split(' ') ?? [],
    labLinks: [],
    demo: { kind: 'concept-cards', variant: slug },
    synonyms: [],
    tags: [lane.toLowerCase(), category.replace(/-/g, ' ')],
  }));
}

